import java.util.*;
import java.util.stream.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = sc.nextInt();
        }

        int n1 = n / 2;
        List<Integer> a1 = new ArrayList<>();
        List<Integer> a2 = new ArrayList<>();

        sumSubset(a, 0, n1, 0, m, a1);
        sumSubset(a, n1, n, 0, m, a2);

        Set<Integer> setA1 = new HashSet<>(a1);
        List<Integer> sortedA1 = new ArrayList<>(setA1);
        Collections.sort(sortedA1);

        int ans = 0;
        for (Integer i : a2) {
            int j = Collections.binarySearch(sortedA1, m - i);
            if (j < 0) {
                j = -j - 1;
            }
            if (j > 0 && ans < sortedA1.get(j - 1) + i) {
                ans = sortedA1.get(j - 1) + i;
            }
        }
        System.out.println(ans);
    }

    private static void sumSubset(int[] a, int start, int end, int sum, int m, List<Integer> res) {
        if (start == end) {
            res.add(sum);
            return;
        }
        sumSubset(a, start + 1, end, (sum + a[start]) % m, m, res);
        sumSubset(a, start + 1, end, sum, m, res);
    }
}

